(()=>{const book=document.querySelector('.captain-book'),stage=document.querySelector('.book-scroll-stage');if(!book||!stage)return;const scene=book.closest('.book-scene');const pages=[...book.querySelectorAll('.captain-log')],controls=book.querySelector('.book-controls'),prev=book.querySelector('.book-prev'),next=book.querySelector('.book-next'),status=book.querySelector('.book-position'),mobile=matchMedia('(max-width:800px)'),reduce=matchMedia('(prefers-reduced-motion:reduce)');let index=-1,frame=0,animations=[];const sheet=book.querySelector('.captain-logs');function measure(){sheet.style.minHeight='';const saved=pages.map(p=>p.hidden);pages.forEach(p=>p.hidden=false);const height=Math.max(...pages.map(p=>p.offsetHeight));pages.forEach((p,i)=>p.hidden=saved[i]);sheet.style.minHeight=height+'px';}measure();document.fonts?.ready.then(()=>{measure();index=-1;schedule()});const clamp=x=>Math.max(0,Math.min(1,x));function draw(){frame=0;const step=2,count=Math.ceil(pages.length/step);if(reduce.matches){stage.style.height='auto';pages.forEach(p=>p.hidden=false);controls.hidden=true;return}const bookHeight=scene.offsetHeight,sticky=90;scene.style.top=sticky+'px';stage.style.height=(Math.max(bookHeight,innerHeight)+innerHeight*.8*(count-1))+'px';const range=stage.offsetHeight-bookHeight;const progress=clamp((sticky-stage.getBoundingClientRect().top)/Math.max(1,range));const group=Math.min(count-1,Math.floor(progress*count));const selected=group*step;if(selected===index)return;const backwards=selected<index;index=selected;animations.forEach(a=>a.cancel());animations=[];pages.forEach((p,i)=>{p.hidden=i<index||i>=index+step;if(!p.hidden){p.style.transformOrigin=backwards?'right center':'left center';animations.push(p.animate([{transform:`perspective(1200px) rotateY(${backwards?16:-16}deg)`,opacity:.45},{transform:'none',opacity:1}],{duration:400,easing:'cubic-bezier(.23,1,.32,1)'}))}});status.textContent=step===1?`Page ${index+1} of 4 · Scroll to turn`:`Pages ${index+1}–${index+2} · Scroll to turn`;prev.disabled=index===0;next.disabled=index+step>=pages.length;}function schedule(){if(!frame)frame=requestAnimationFrame(draw)}function go(delta){const step=2,count=Math.ceil(pages.length/step),group=Math.max(0,Math.min(count-1,index/step+delta));const top=scrollY+stage.getBoundingClientRect().top-parseFloat(scene.style.top||90)+(stage.offsetHeight-scene.offsetHeight)*(group+.15)/count;window.scrollTo({top,behavior:reduce.matches?'instant':'smooth'})}prev.onclick=()=>go(-1);next.onclick=()=>go(1);controls.hidden=false;book.classList.add('book-ready');addEventListener('scroll',schedule,{passive:true});addEventListener('resize',()=>{measure();index=-1;schedule()},{passive:true});mobile.addEventListener('change',()=>{measure();index=-1;schedule()});reduce.addEventListener('change',()=>{index=-1;schedule()});draw()})();
